// src/quest/silent-friday/story.ts — "Silent Friday", the guild's first Grand Quest (forensics). Chapters 0-6: the
// prologue (who Sir Prince was, the night he died, the contract), the scene of his murder (challenge 1: the drawing's
// hidden comment), the girl at Arandelle theme park (challenge 2: the "text file" that is a picture with a second one
// packed behind it), the Hale fire (challenge 3: a forged drawing whose IHDR hides the rows below it), The Fool's
// circus (challenge 4: Hale's ledger, a workbook whose real book is a "veryHidden" sheet behind a hidden decoy), the
// Hero's son (challenge 5: a music box whose right channel has words drawn in its spectrogram), and The Fool's death
// (challenge 6: Hale's diary, a PDF with black boxes over live text and a line rewritten by an incremental update).
// The story is a spoiler for the challenges: it lives on the server and leaves it one unlocked chapter at a time.
// Varrick, Master Hale and The Fool have their own portraits (static/quest/sf/sprite); Sir Prince stays a crowned
// silhouette for now (shadow-prince, cut from Roland's outline), like the minor parts. `face` is the way each portrait
// looks as drawn (the stage mirrors it so the two sides of a talk face each other); `voice` is the pitch of its blips.
// Key phrases are marked **like this**;
// each chapter closes its first half with case notes, and carries a short recap for a player who skips ahead.
import type { Chapter, Quest, Step, Text } from '../types.js';

const T = (en: string, id: string): Text => ({ en, id });
const narr = (en: string, id: string): Step => ({ narr: T(en, id) });
type LineOpts = { pose?: string; style?: 'shout' | 'whisper'; react?: 'shake' | 'jump'; off?: boolean };
const say = (who: string, en: string, id: string, o: string | LineOpts = {}): Step =>
  ({ say: who, text: T(en, id), ...(typeof o === 'string' ? { pose: o } : o) });
const clue = (en: string, id: string): Step => ({ clue: T(en, id) });

